A safer **Focus Support** module can detect voluntary signals, avoid reading sensitive content, and offer help without blocking external resources:

```python
def support_focus_without_lockin(
    user_id,
    activity_data,
    tutor_state,
    consent,
    user_preferences
):
    """
    Privacy-preserving focus support.

    Does not:
      - inspect clipboard contents
      - read browser history or URLs
      - block app switching
      - discourage legitimate external resources
      - infer emotional state from multitasking alone
    """

    if not consent.focus_support_enabled:
        return {
            "action": "none",
            "reason": "focus support disabled"
        }

    # Use coarse, opt-in signals only.
    alt_tab_count = activity_data.get("alt_tab_count", 0)

    # Ignore isolated context switches; they are ambiguous.
    repeated_switching = (
        alt_tab_count >= user_preferences.get("switch_threshold", 4)
        and tutor_state.active_task_duration >= 5 * 60
    )

    if not repeated_switching:
        return {
            "action": "none",
            "reason": "no reliable focus-friction signal"
        }

    # Offer choices rather than attempting to retain the user.
    return {
        "action": "offer_support_menu",
        "message": (
            "Would you like a hint, a simpler example, a quick recap, "
            "or a two-minute break? You can also use outside resources."
        ),
        "options": [
            "scaffolding_hint",
            "simpler_example",
            "quick_recap",
            "take_break",
            "continue_independently",
            "use_external_resources"
        ],
        "reason": "repeated context switching may indicate task friction",
        "telemetry": {
            "store_raw_activity": False,
            "share_with_tutor": False
        }
    }
```

