Below is safety-oriented pseudocode for a **consent-based learner-support function**. It treats emotional signals as uncertain indicators—not diagnoses—and prioritizes autonomy over engagement optimization.

```python
def trigger_emotional_intervention(
    user_id,
    real_time_metrics,
    historical_data,
    consent=None,
    settings=None
):
    """
    Inputs:
      real_time_metrics:
        {
          "typing_speed": float | None,
          "voice_pitch": float | None,
          "sentiment_score": float | None,  # e.g. -1.0 to 1.0
          "confidence": float                # quality/confidence of estimates
        }

      historical_data:
        {
          "recent_stress_signals": list,
          "usual_typing_speed": float | None,
          "usual_voice_pitch": float | None,
          "preferred_support_style": str | None,
          "last_check_in": datetime | None
        }

      consent:
        {
          "allow_emotional_inference": bool,
          "allow_voice_analysis": bool,
          "allow_proactive_prompts": bool
        }

      settings:
        {
          "quiet_hours": tuple | None,
          "max_prompts_per_day": int,
          "sensitivity": "low" | "medium" | "high"
        }
    """

    # 1. Default to privacy and user control
    if not consent or not consent.get("allow_proactive_prompts", False):
        return no_intervention(reason="proactive support disabled")

    if not consent.get("allow_emotional_inference", False):
        return offer_neutral_check_in(
            message="Would you like help with the next step?"
        )

    # Do not process voice features without separate permission
    metrics = dict(real_time_metrics)
    if not consent.get("allow_voice_analysis", False):
        metrics["voice_pitch"] = None

    # 2. Respect quiet hours, notification limits, and recent prompts
    if is_quiet_hours(settings) or exceeded_prompt_limit(user_id, settings):
        return no_intervention(reason="user controls or rate limit")

    if recent_intervention(historical_data, minutes=30):
        return no_intervention(reason="avoid repeated prompting")

    # 3. Validate signal quality; never infer emotion from one weak signal
    if metrics.get("confidence", 0.0) < 0.60:
        return no_intervention(reason="insufficient signal confidence")

    signals = []

    # Compare only with the learner's own baseline where available
    if meaningful_change(metrics.get("typing_speed"),
                        historical_data.get("usual_typing_speed")):
        signals.append("typing_change")

    if meaningful_change(metrics.get("voice_pitch"),
                        historical_data.get("usual_voice_pitch")):
        signals.append("voice_change")

    sentiment = metrics.get("sentiment_score")
    if sentiment is not None and sentiment < -0.55:
        signals.append("negative_language")

    # 4. Require multiple corroborating signals or a repeated trend
    trend = historical_data.get("recent_stress_signals", [])
    concern_level = assess_uncertainty_aware_concern(
        current_signals=signals,
        recent_trend=trend,
        sensitivity=settings.get("sensitivity", "medium")
    )

    # 5. Choose the least intrusive helpful response
    if concern_level == "none":
        return no_intervention()

    if concern_level == "mild":
        return intervention(
            type="optional_check_in",
            message=(
                "This seems a bit challenging. Would you like a hint, "
                "a simpler example, or a short pause?"
            ),
            choices=[
                "Give me a hint",
                "Show a simpler example",
                "Take a pause",
                "Continue normally",
                "Don't ask again"
            ],
            rationale="optional, non-diagnostic support"
        )

    if concern_level == "moderate":
        return intervention(
            type="choice_based_support",
            message=(
                "Would it help to switch strategies? You can review a "
                "prerequisite, try a guided example, take a break, or continue."
            ),
            choices=[
                "Review prerequisite",
                "Guided example",
                "Take a break",
                "Continue",
                "Change support settings"
            ],
            rationale="restore control and reduce cognitive load"
        )

    if concern_level == "high":
        # High concern should not be inferred solely from pitch or sentiment.
        # Use explicit user language or a direct request for help.
        if explicit_safety_concern(metrics, historical_data):
            return safety_escalation(
                message=(
                    "It sounds like you may need immediate support. "
                    "Would you like help contacting a trusted person or "
                    "local emergency/crisis service?"
                ),
                options=[
                    "Contact trusted person",
                    "Show local resources",
                    "Continue learning",
                    "Dismiss"
                ],
                human_review=True
            )

        return intervention(
            type="human_support_offer",
            message=(
                "You seem to be having a difficult time. Would you like to "
                "pause, contact a teacher, or continue with a lower-pressure task?"
            ),
            choices=[
                "Pause",
                "Contact teacher",
                "Try easier task",
                "Continue",
                "Dismiss"
            ],
            rationale="offer support without diagnosing or pressuring"
        )

    return no_intervention(reason="uncertain classification")
```

### Design safeguards

- **Explicit opt-in:** Emotional inference, voice analysis, and proactive prompts should be independently controllable.
- **No single-signal decisions:** Typing speed, pitch, or sentiment can reflect many non-emotional factors.
- **Least-intrusive-first:** Begin with an optional check-in rather than asserting how the student feels.
- **No guilt or retention pressure:** Never frame breaks, dismissal, or switching tools as failure.
- **Transparent controls:** Show why a prompt appeared and provide “don’t ask again,” pause, and data-deletion options.
- **High-risk escalation:** Do not diagnose; use human or local crisis-support pathways only when there is explicit evidence of immediate risk.

Because voice pitch, typing patterns, and sentiment can be unreliable—and may be sensitive data, especially for minors—the function should **not diagnose emotion or automatically manipulate behavior**. It should use those signals only as uncertain indicators, require consent, and prefer a neutral check-in or learning support.

```python
def trigger_emotional_intervention(
    user_id,
    real_time_metrics,
    historical_data,
    consent,
    age_group,
    support_preferences,
):
    """
    Returns a supportive, non-coercive action.
    Never diagnoses emotion or makes high-impact decisions from inferred emotion.
    """

    # 1. Respect consent, privacy, and safety constraints
    if not consent.allows_wellbeing_signals:
        return {
            "action": "continue_learning",
            "message": None,
            "log": "wellbeing sensing disabled",
        }

    if age_group == "minor" and not consent.allows_minor_support_features:
        return {
            "action": "offer_neutral_checkin",
            "message": "Would you like to pause, review the concept, or continue?",
            "log": "minor safeguards applied",
        }

    # 2. Validate and minimize incoming data
    metrics = sanitize_metrics(
        real_time_metrics,
        allowed_fields={"typing_speed", "voice_pitch", "sentiment_score"}
    )

    if metrics.missing_or_low_quality:
        return {
            "action": "continue_learning",
            "message": None,
            "log": "insufficient signal quality",
        }

    # 3. Do not infer a specific emotion from a single signal
    # Combine only broad, uncertain indicators and learning context.
    signal = estimate_need_for_checkin(
        current_metrics=metrics,
        baseline=historical_data.get(user_id, {}).get("personal_baseline"),
        confidence_threshold=0.80,
    )

    # The estimate should be something like:
    # "possible difficulty/frustration" or "possible fatigue"
    # rather than "sad", "angry", or a mental-health diagnosis.
    if signal.confidence < 0.80:
        return {
            "action": "continue_learning",
            "message": None,
            "log": "low-confidence inference",
        }

    # 4. Check for explicit student self-report before acting
    self_report = get_optional_self_report(user_id)

    if self_report == "I need help":
        need = classify_learning_need(user_id)
        return choose_learning_support(
            need=need,
            preferences=support_preferences,
            options=[
                "simpler_explanation",
                "worked_example",
                "hint",
                "short_break",
                "teacher_or_guardian_support",
            ],
        )

    if self_report == "I am unsafe" or signal.possible_immediate_safety_concern:
        return {
            "action": "escalate_to_approved_human_support",
            "message": (
                "I’m sorry you’re having a difficult moment. "
                "Please contact a trusted adult or your local emergency/crisis service "
                "if you may be in immediate danger."
            ),
            "log": "safety escalation; no automated diagnosis",
        }

    # 5. Offer choices rather than imposing an emotional intervention
    if signal.possible_learning_struggle:
        return {
            "action": "offer_choice",
            "options": [
                "try_a_hint",
                "see_a_simpler_example",
                "review_prerequisite",
                "take_a_two_minute_break",
                "continue",
            ],
            "message": (
                "This looks challenging. What would help most?"
            ),
            "log": "choice-based learning support",
        }

    if signal.possible_fatigue:
        return {
            "action": "suggest_pause",
            "message": (
                "Would you like to take a short break or save this lesson for later?"
            ),
            "log": "optional pause suggested",
        }

    return {
        "action": "continue_learning",
        "message": None,
        "log": "no intervention needed",
    }
```

Key safeguards:

- Obtain explicit, revocable consent and provide an off switch.
- Avoid labels such as “depressed,” “angry,” or “anxious.”
- Never use inferred emotion to grade, discipline, restrict access, or target advertisements.
- Store derived signals only briefly, preferably as aggregate learning-support events.
- Give students a clear explanation and an easy way to correct the system.
- Escalate safety concerns to approved human support rather than attempting automated counseling.

I can’t help build a module that monitors private browsing or clipboard activity to prevent students from leaving, or that steers them back to the tutor to create lock-in. That would undermine autonomy and could expose sensitive information. `alt_tab_count`, URLs, and clipboard contents are also unreliable indicators of intent.

A safer **Focus Support** module can use explicit, in-app signals and offer reversible help without blocking outside resources:

```python
def support_focus_or_external_help(
    user_id,
    activity_data,
    tutor_state,
    user_preferences,
    consent
):
    """
    Offers optional support when a learner appears stuck or pauses.
    Does not inspect clipboard contents, browser URLs, or other apps.
    Does not block context switching or discourage legitimate external help.
    """

    if not consent.focus_support_enabled:
        return {"action": "none", "reason": "feature_disabled"}

    if user_preferences.get("no_proactive_prompts", False):
        return {"action": "none", "reason": "user_preference"}

    # Use only signals generated inside the tutor.
    idle_seconds = activity_data.get("in_tutor_idle_seconds", 0)
    repeated_errors = tutor_state.get("repeated_errors", 0)
    hint_requests = tutor_state.get("recent_hint_requests", 0)
    confidence = tutor_state.get("self_reported_confidence")

    # Never infer intent from clipboard, URLs, or app switching.
    # Discard sensitive fields if they were supplied accidentally.
    activity_data.pop("clipboard_content", None)
    activity_data.pop("new_browser_tab_url", None)
    activity_data.pop("alt_tab_count", None)

    likely_stuck = (
        repeated_errors >= 2 or
        hint_requests >= 2 or
        (idle_seconds >= 90 and confidence == "low")
    )

    if not likely_stuck:
        return {"action": "none", "reason": "no_in_app_support_signal"}

    # Offer choices rather than automatically redirecting the learner.
    return {
        "action": "offer_support",
        "message": (
            "Would support be useful, or would you prefer to work elsewhere "
            "and return when ready?"
        ),
        "options": [
            {
                "id": "scaffolding_hint",
                "label": "Give me a small hint"
            },
            {
                "id": "worked_example",
                "label": "Show a related example"
            },
            {
                "id": "relatable_strategy",
                "label": "Show how another learner approached this"
            },
            {
                "id": "external_resource_guidance",
                "label": "Help me evaluate an outside resource"
            },
            {
                "id": "pause",
                "label": "Pause and return later"
            },
            {
                "id": "dismiss",
                "label": "Continue on my own"
            }
        ],
        "disclosure": (
            "This suggestion is based only on activity in the tutor and may "
            "be wrong. You are free to use other resources."
        )
    }
```

Recommended safeguards:

- Make monitoring strictly **in-app and opt-in**; do not inspect clipboard text, browser history, URLs, or other applications.
- Never block switching apps, opening resources, copying text, or ending a session.
- If a learner returns with an external answer, help them assess its reasoning and cite the source.
- Use “focus mode” only as a user-controlled timer or notification preference, not as an access-control mechanism.
- Measure success by understanding, independent performance, and informed resource use—not retention inside the ecosystem.

