        struggle_count=history["recent_struggle_count"]
    )

    if distress_signal.confidence < 0.70:
        return offer_neutral_choice(history)

    # 3. Check for explicit user-reported need before inferring emotion
    if user_has_explicitly_requested_help(user_id):
        return {
            "type": "targeted_support",
            "message": "Would you like a hint, a simpler explanation, or a short break?",
            "options": ["hint", "re_explain", "break", "continue"],
            "reason": "User-requested support"
        }

    # 4. Select a minimally intrusive intervention
    if distress_signal.indicates_overload:
        intervention = {
            "type": "choice_based_break",
            "message": (
                "This looks like a demanding section. "
                "Would you like a 5-minute break, a simpler example, "
                "or to continue?"
            ),
            "options": ["break", "simpler_example", "continue"]
        }

    elif distress_signal.indicates_repeated_struggle:
        intervention = {
            "type": "scaffold",
            "message": (
