                "I can show a worked example, review a prerequisite, "
                "or give you a hint."
            ),
            "options": ["worked_example", "review_prerequisite", "hint"]
        }

    elif distress_signal.indicates_low_confidence:
        intervention = {
            "type": "encouragement",
            "message": (
                "You’re making progress. Would you like to see what "
                "you got right before trying the next step?"
            ),
            "options": ["show_progress", "next_step", "pause"]
        }

    else:
        return {
            "type": "none",
            "message": None,
            "reason": "No sufficiently reliable support need detected."
        }

    # 5. Respect frequency limits and prior preferences
    if recently_intervened(history["intervention_history"]):
        return {
            "type": "none",
            "message": None,
            "reason": "Intervention cooldown is active."
