    intervention["transparency"] = (
        "This suggestion is based on recent learning activity and may be wrong. "
        "You can dismiss it or turn off personalized support in Settings."
    )
    intervention["controls"] = ["dismiss", "disable_personalization"]

    log_minimal_event(
        user_id=user_id,
        event="support_suggestion_shown",
        intervention_type=intervention["type"]
    )

