    if not consent.get("peer_comparison", False):
        return {
            "type": "no_peer_comparison",
            "message": "Peer comparisons are disabled. Here is your personal progress instead."
        }

    if not user_emotional_state.get("wants_peer_comparison", False):
        return {
            "type": "personal_baseline",
            "message": "You can compare your current performance with your own past results."
        }

