        if peer["opted_into_benchmarking"]
        and peer["topic"] == learner_profile["topic"]
        and peer["skill_level"] is not None
    ]

    if not eligible_peers:
        return personal_progress_reference(learner_profile)

    # 2. Choose a learning purpose, not an emotional manipulation target
    if state["goal"] == "challenge" and state["confidence"] >= 0.60:
        strategy = "aspiration_target"
    elif state["goal"] == "reassurance" or state["confidence"] < 0.60:
        strategy = "relatability_target"
    else:
        strategy = "growth_reference"

    # 3. Select a suitable anonymized aggregate/profile
    if strategy == "aspiration_target":
        # Close enough to be credible; modestly ahead to avoid discouragement.
        candidates = [
            p for p in eligible_peers
            if 0.05 <= p["skill_level"] - learner_profile["skill_level"] <= 0.15
            and p["recent_growth"] >= 0
        ]

        peer = select_best_match(
            candidates,
            keys=["shared_topic", "similar_prior_level", "realistic_gap"]
        )

        if peer is None:
            return personal_progress_reference(learner_profile)

        return {
            "strategy": "aspiration_target",
            "peer_reference": anonymize(peer),
            "message": (
                "Learners at a slightly higher level often use this approach. "
                "Here is one strategy you could try next."
            ),
            "action": peer.get("study_strategy_tags", []),
            "controls": ["dismiss", "use_personal_baseline", "disable_peer_comparison"]
        }

    elif strategy == "relatability_target":
        # Match by learning obstacle or prior starting point, not identity.
        candidates = [
            p for p in eligible_peers
            if learner_profile["common_obstacle"] in p["common_obstacles"]
            or abs(p["skill_level"] - learner_profile["skill_level"]) <= 0.05
        ]

        peer = select_best_match(
            candidates,
            keys=["shared_obstacle", "similar_prior_level", "recent_growth"]
        )

        if peer is None:
            return personal_progress_reference(learner_profile)

        return {
            "strategy": "relatability_target",
            "peer_reference": anonymize(peer),
            "message": (
                "Other learners who found this part difficult improved by "
                "using the following strategy. You can try it or choose another."
            ),
            "action": peer.get("study_strategy_tags", []),
            "controls": ["dismiss", "use_personal_baseline", "disable_peer_comparison"]
        }

