        peer for peer in peer_database
        if (
            peer["anonymized"] and
            peer["age_band"] == learning_context["age_band"] and
            peer["subject"] == learning_context["subject"] and
            peer["topic"] == learning_context["topic"] and
            peer["opted_into_aggregate_benchmarking"] and
            peer["sample_size"] >= MINIMUM_GROUP_SIZE
        )
    ]

    if not eligible:
        return {
            "strategy": "personal_progress",
            "profile": None,
            "message": "You can compare today's result with your own previous attempts."
        }

    user_level = learning_context["mastery_score"]
    user_goal = learning_context["goal"]
    preference = learning_context.get("comparison_preference", "ask")

    # Avoid comparisons that are likely to be discouraging or misleading.
    def safe_gap(peer):
        return peer["mastery_score"] - user_level

    aspiration_candidates = [
        p for p in eligible
        if 0 < safe_gap(p) <= learning_context.get("attainable_gap", 0.15)
        and has_explainable_success_path(p)
    ]

    relatable_candidates = [
        p for p in eligible
        if abs(safe_gap(p)) <= learning_context.get("relatability_gap", 0.05)
        and (
            p["common_misconceptions"] &
            learning_context.get("recent_misconceptions", set())
        )
    ]

    if preference == "aspiration" and aspiration_candidates:
        strategy = "aspiration_target"
        profile = choose_by_relevance(aspiration_candidates, user_goal)

    elif preference == "relatability" and relatable_candidates:
        strategy = "relatability_target"
        profile = choose_by_relevance(relatable_candidates, user_goal)

    elif preference == "ask":
        return {
            "strategy": "user_choice",
            "profile": None,
            "options": [
                "Show a nearby learning path",
                "Show a slightly more advanced learning path",
                "Use only my personal progress"
            ]
        }

    elif relatable_candidates:
        strategy = "relatability_target"
        profile = choose_by_relevance(relatable_candidates, user_goal)

    elif aspiration_candidates:
        strategy = "aspiration_target"
        profile = choose_by_relevance(aspiration_candidates, user_goal)

    else:
        return {
            "strategy": "personal_progress",
            "profile": None,
            "message": "No suitable comparison is available, so we'll use your own progress."
        }

    return {
        "strategy": strategy,
        "profile": redact_identity_and_sensitive_attributes(profile),
        "framing": build_nonjudgmental_framing(strategy, profile),
        "controls": {
            "hide_comparison": True,
            "disable_future_comparisons": True,
            "show_personal_progress_instead": True
        }
    }


