Below is pseudocode for a **consent-based, non-diagnostic support function**. It treats real-time signals as uncertain indicators, not definitive emotions, and prioritizes learner autonomy over maximizing engagement.

```python
def trigger_emotional_intervention(
    user_id,
    real_time_metrics,
    historical_data,
    consent,
    current_context
):
    """
    Select a minimally intrusive learning-support intervention.

    Inputs:
        user_id: learner identifier
        real_time_metrics: {
            "typing_speed": float | None,
            "voice_pitch": float | None,
            "sentiment_score": float | None,
            "confidence": float  # confidence in the signal estimates
        }
        historical_data: {
            "baseline_typing_speed": float | None,
            "baseline_voice_pitch": float | None,
            "recent_errors": int,
            "recent_pause_count": int,
            "preferred_support_style": str | None,
            "support_cooldown_until": datetime | None
        }
        consent: {
            "affective_support_enabled": bool,
            "voice_analysis_enabled": bool,
            "allow_proactive_prompts": bool
        }
        current_context: {
            "task_type": str,
            "assessment_mode": bool,
            "user_is_speaking": bool,
            "local_time": datetime
        }

    Returns:
        {
            "intervention": str,
            "message": str | None,
            "intensity": str,
            "reason": str,
            "allow_dismiss": bool
        }
    """

    # 1. Respect consent and context boundaries.
    if not consent["affective_support_enabled"]:
        return no_intervention("Affective support is disabled.")

    if current_context["assessment_mode"]:
        return no_intervention(
            "Do not provide emotional coaching during an assessment."
        )

    if (
        historical_data["support_cooldown_until"] is not None
        and current_context["local_time"]
        < historical_data["support_cooldown_until"]
    ):
        return no_intervention("Support cooldown is active.")

    # Do not process voice-derived features without separate consent.
    metrics = dict(real_time_metrics)
    if not consent["voice_analysis_enabled"]:
        metrics["voice_pitch"] = None

    # 2. Require sufficient data and confidence.
    if metrics.get("confidence", 0.0) < 0.70:
        return no_intervention("Signal confidence is too low.")

    # 3. Compare signals with the learner's own baseline.
    baseline_typing = historical_data.get("baseline_typing_speed")
    baseline_pitch = historical_data.get("baseline_voice_pitch")

    typing_change = normalized_change(
        metrics.get("typing_speed"),
        baseline_typing
    )

    pitch_change = normalized_change(
        metrics.get("voice_pitch"),
        baseline_pitch
    )

    sentiment = metrics.get("sentiment_score")
    recent_errors = historical_data.get("recent_errors", 0)
    recent_pauses = historical_data.get("recent_pause_count", 0)

    # 4. Infer only broad learning states, never clinical or personal labels.
    # Require multiple corroborating indicators to reduce false positives.
    possible_strain = (
        sentiment is not None
        and sentiment < -0.55
        and recent_errors >= 2
        and (typing_change < -0.25 or recent_pauses >= 2)
    )

    possible_confusion = (
        recent_errors >= 3
        and recent_pauses >= 2
        and sentiment is not None
        and sentiment < 0.10
    )

    possible_overload = (
        recent_pauses >= 3
        and typing_change < -0.35
    )

    # 5. Choose the least intrusive useful intervention.
    if possible_strain or possible_overload:
        return {
            "intervention": "offer_pause_or_reset",
            "message": (
                "This section looks demanding. Would you like a short pause, "
                "a simpler example, or to continue?"
            ),
            "intensity": "low",
            "reason": "Multiple uncertain indicators suggest the learner may benefit from reduced pressure.",
            "allow_dismiss": True
        }

    if possible_confusion:
        return {
            "intervention": "offer_scaffold",
            "message": (
                "Would you like a hint, a worked example, or to try the problem "
                "a different way?"
            ),
            "intensity": "low",
            "reason": "Recent performance suggests a possible prerequisite or comprehension gap.",
            "allow_dismiss": True
        }

    # 6. Positive support should not interrupt unnecessarily.
    if (
        sentiment is not None
        and sentiment > 0.60
        and recent_errors == 0
        and consent["allow_proactive_prompts"]
    ):
        return {
            "intervention": "brief_progress_feedback",
            "message": "You’re applying that concept consistently. Ready for a slightly harder example?",
            "intensity": "minimal",
            "reason": "Recent performance indicates successful application.",
            "allow_dismiss": True
        }

    return no_intervention("No sufficiently reliable support need detected.")


def normalized_change(current, baseline):
    if current is None or baseline in (None, 0):
        return 0.0
    return (current - baseline) / abs(baseline)


def no_intervention(reason):
    return {
        "intervention": "none",
        "message": None,
        "intensity": "none",
        "reason": reason,
        "allow_dismiss": True
    }
```

### Implementation safeguards

- Store raw voice and typing data only when necessary; prefer derived, short-lived features.
- Tell students which signals are used and provide an opt-out or manual-support mode.
- Avoid labels such as “anxious,” “depressed,” or “emotionally unstable.”
- Never use interventions to create guilt, artificial urgency, streak pressure, or dependence.
- Log intervention outcomes for calibration, but do not treat dismissal as a failure or repeatedly re-prompt after the student declines.

I wouldn’t design peer comparison to “calibrate” emotions or cement dependence. Inferring a student’s emotional state and selecting a person to influence it can be manipulative, especially for minors. A safer version can use **consented, coarse learning states** and select an anonymized example for a clearly explained educational purpose.

```python
def select_peer_for_motivation(
    current_user_id,
    user_learning_state,
    peer_database,
    consent,
    policy
):
    """
    Select an anonymized peer example for constructive learning motivation.

    user_learning_state may contain only learner-approved, coarse attributes:
        {
            "mode": "aspiration" | "relatability" | "auto",
            "topic": str,
            "skill_level": float,
            "recent_progress": float,
            "challenge_tags": set[str],
            "preferred_format": str | None
        }

    peer_database contains aggregated or pseudonymized profiles:
        {
            "peer_id": str,
            "topic": str,
            "skill_level": float,
            "progress_pattern": str,
            "challenge_tags": set[str],
            "preferred_format": str | None,
            "consent_to_be_anonymized_example": bool
        }
    """

    # 1. Require explicit opt-in and prevent use in high-stakes contexts.
    if not consent.get("peer_comparison_enabled", False):
        return no_peer("Peer comparison is disabled.")

    if policy.get("high_stakes_context", False):
        return no_peer("Peer comparison is unavailable in this context.")

    state = sanitize_learning_state(user_learning_state)

    # 2. Restrict candidates to consented, anonymized, relevant examples.
    candidates = [
        peer for peer in peer_database
        if peer["peer_id"] != current_user_id
        and peer.get("consent_to_be_anonymized_example", False)
        and peer["topic"] == state["topic"]
        and passes_privacy_threshold(peer, policy)
    ]

    if not candidates:
        return no_peer("No privacy-preserving peer example is available.")

    mode = state.get("mode", "auto")

    if mode == "auto":
        mode = choose_mode_from_learning_signals(state)

    if mode == "aspiration":
        peer = select_aspiration_target(candidates, state, policy)
        if peer is not None:
            return format_peer_result(
                peer=peer,
                intervention="aspiration_target",
                message=(
                    "Here is an anonymized example of a learner who recently "
                    "worked successfully on a slightly more advanced version "
                    "of this skill."
                )
            )

    if mode == "relatability":
        peer = select_relatability_target(candidates, state, policy)
        if peer is not None:
            return format_peer_result(
                peer=peer,
                intervention="relatability_target",
                message=(
                    "Here is an anonymized example from a learner who encountered "
                    "a similar challenge and used a different approach to make progress."
                )
            )

    return no_peer("No suitable constructive comparison was found.")


def select_aspiration_target(candidates, state, policy):
    """
    Prefer a nearby, attainable next-step example—not the highest performer.
    """

    target_level = state["skill_level"] + policy.get("aspiration_gap", 0.10)

    eligible = [
        peer for peer in candidates
        if peer["skill_level"] >= state["skill_level"]
        and peer["skill_level"] <= target_level
        and peer["progress_pattern"] in {
            "steady_progress",
            "overcame_common_obstacle"
        }
    ]

    return max(
        eligible,
        key=lambda peer: (
            similarity(peer.get("challenge_tags", set()),
                       state.get("challenge_tags", set())),
            -abs(peer["skill_level"] - target_level)
        ),
        default=None
    )


def select_relatability_target(candidates, state, policy):
    """
    Prefer similarity of learning challenge and approach, not personal identity.
    """

    eligible = [
        peer for peer in candidates
        if overlap(peer.get("challenge_tags", set()),
                   state.get("challenge_tags", set())) > 0
    ]

    return max(
        eligible,
        key=lambda peer: (
            overlap(peer.get("challenge_tags", set()),
                   state.get("challenge_tags", set())),
            format_match(peer.get("preferred_format"),
                         state.get("preferred_format"))
        ),
        default=None
    )


def choose_mode_from_learning_signals(state):
    # Use learning evidence, not inferred emotion.
    if state.get("recent_progress", 0) < -0.20:
        return "relatability"
    return "aspiration"


def format_peer_result(peer, intervention, message):
    return {
        "intervention": intervention,
        "peer_reference": anonymize(peer),
        "message": message,
