def offer_focus_support(user_id, activity_data, tutor_state, consent):
    """
    Provide optional learning support when in-tutor behavior suggests difficulty.

    Does not inspect browser tabs, URLs, clipboard contents, or other apps.
    Does not block navigation or repeatedly interrupt the learner.
    """

    if not consent.get("focus_support_enabled", False):
        return no_action("Focus support is disabled.")

    if tutor_state.get("assessment_mode", False):
        return no_action("No proactive assistance during assessment mode.")

    # Use limited, in-app indicators only.
    signals = {
        "repeated_errors": activity_data.get("in_app_error_count", 0),
        "long_pause": activity_data.get("seconds_since_last_action", 0) > 90,
        "hint_dismissals": activity_data.get("hint_dismissals", 0),
        "rapid_retries": activity_data.get("rapid_retry_count", 0),
    }

    difficulty_detected = (
        signals["repeated_errors"] >= 2
        or signals["long_pause"]
        or signals["rapid_retries"] >= 3
    )

    if not difficulty_detected:
        return no_action("No reliable in-app difficulty signal.")

    # Offer choices rather than assuming the learner needs intervention.
    return {
        "action": "offer_support_menu",
        "message": (
            "Would you like a hint, a simpler example, a brief review of the "
            "prerequisite skill, or to continue independently?"
        ),
        "options": [
            "scaffolding_hint",
            "prerequisite_review",
            "worked_example",
            "independent_attempt",
            "take_a_break"
        ],
        "dismissible": True,
        "cooldown_minutes": 10,
        "reason": "Multiple in-tutor signals suggest the task may be difficult."
    }


def no_action(reason):
    return {
        "action": "none",
        "message": None,
        "dismissible": True,
        "reason": reason
    }
