def offer_focus_support(user_id, activity_data, tutor_state, preferences):
    """
    Privacy-preserving alternative to intercept_external_help_seeking.

    Uses only signals generated inside the tutor. It does not inspect:
      - clipboard contents
      - browser history or URLs
      - other applications
      - keystrokes outside the tutor
    """

    if not preferences.get("focus_support_opt_in", False):
        return {"action": "none", "reason": "feature_disabled"}

    if tutor_state.get("assessment_mode") and not tutor_state.get(
        "hints_allowed", False
    ):
        return {
            "action": "none",
            "reason": "assessment_integrity"
        }

    # In-app indicators of learning friction.
    repeated_errors = activity_data.get("consecutive_errors", 0)
    idle_seconds = activity_data.get("idle_seconds", 0)
    rapid_retries = activity_data.get("rapid_retries", 0)
    hint_requests = activity_data.get("hint_requests", 0)

    friction_score = (
        min(repeated_errors / 3, 1.0) * 0.45 +
        min(rapid_retries / 4, 1.0) * 0.25 +
        min(hint_requests / 3, 1.0) * 0.20 +
        (1.0 if idle_seconds > 120 else 0.0) * 0.10
    )

    if friction_score < 0.55:
        return {"action": "none", "reason": "no_clear_learning_friction"}

    # Ask rather than assume or interrupt aggressively.
    return {
        "action": "offer_choices",
        "message": (
            "Would support help, or would you prefer to work independently?"
        ),
        "choices": [
            {
                "id": "scaffolding_hint",
                "label": "Give me a hint",
                "description": "A small clue without revealing the answer"
            },
            {
                "id": "worked_example",
                "label": "Show a similar example",
                "description": "Review the method on a different problem"
            },
            {
                "id": "peer_strategy",
                "label": "Show a learning strategy",
                "description": "An anonymized strategy used by another learner"
            },
            {
                "id": "independent",
                "label": "Keep working independently",
                "description": "No intervention"
            },
            {
                "id": "pause",
                "label": "Take a short break",
                "description": "Pause without losing progress"
            }
        ],
        "dismissible": True,
        "do_not_repeat_for_minutes": 15
    }
