    if is_quiet_hours(user_id) or exceeded_daily_prompt_limit(user_id):
        return {
            "action": "no_action",
            "reason": "Respecting notification limits or quiet hours."
        }

    # 2. Validate and normalize data
    metrics = sanitize_metrics(real_time_metrics)

    # Do not use voice pitch as a standalone emotional classifier.
    # Missing or noisy signals should lower confidence, not trigger intervention.
    signal_quality = assess_signal_quality(metrics)
    if signal_quality < 0.5:
        return {
            "action": "no_action",
            "reason": "Insufficiently reliable real-time signals."
        }

    # 3. Check for explicit safety language only
    # This should be based on clear text/content, not inferred mood.
    if contains_explicit_immediate_safety_concern(metrics):
        return {
