                "contact_trusted_person",
                "continue_when_ready"
            ],
            "human_review": True
        }

    # 4. Compare current learning behavior with the student's own baseline.
    # Avoid making population-level assumptions about mood or ability.
    baseline = historical_data.get("learning_baseline", {})
    changes = compare_with_personal_baseline(metrics, baseline)

    # 5. Select the least intrusive useful intervention.
    # Signals are treated as uncertainty, not proof of an emotional state.
    if changes.get("sustained_struggle", False):
        return {
            "action": "offer_scaffold",
            "message": (
                "This topic seems to be taking extra effort. "
                "Would you like a simpler explanation, an example, or a short break?"
            ),
            "options": [
                "simpler_explanation",
                "worked_example",
                "practice_easier_problem",
                "take_break",
                "dismiss"
            ],
            "rationale": "Observed learning difficulty relative to the user's baseline."
        }

    if changes.get("rapid_pacing_or_rushing", False):
        return {
            "action": "offer_pacing_support",
            "message": (
                "Would you like to slow down and review the key idea before continuing?"
            ),
            "options": [
                "review_key_idea",
                "continue",
                "dismiss"
            ],
            "rationale": "Current pace may reduce retention; no emotional state inferred."
        }

    if changes.get("possible_frustration", False):
        return {
            "action": "brief_check_in",
            "message": (
                "How would you like to proceed?"
            ),
            "options": [
                "try_hint",
                "see_another_explanation",
                "switch_activity",
                "take_break",
                "dismiss"
            ],
            "rationale": (
                "Multiple weak signals suggest the current activity may be difficult; "
                "the student chooses the response."
            )
        }

    # 6. Reinforce autonomy and learning—not engagement for its own sake.
    if is_good_time_for_reflection(user_id, historical_data):
        return {
            "action": "optional_reflection",
            "message": (
                "Before moving on, would you like to explain the idea in your own words?"
            ),
            "options": [
                "reflect",
                "continue",
                "dismiss"
            ],
            "rationale": "Retrieval and explanation can improve retention."
        }

