def select_peer_for_motivation(
    current_user_id,
    user_emotional_state,  # used only to choose support intensity, not exploit emotion
    peer_database,
    user_preferences,
    learning_context
):
    """
    Return a privacy-preserving learning benchmark or anonymized example.

    No identifiable peer is exposed.
    Emotional state never overrides consent or is used to pressure engagement.
    """

    # 1. Check consent and comparison preferences.
    if not user_preferences.get("peer_comparisons_enabled", False):
        return {
            "mode": "no_comparison",
            "action": "personal_progress_feedback"
        }

    if user_preferences.get("avoid_social_comparison", False):
        return {
            "mode": "personal_progress_feedback",
            "action": "compare_against_own_prior_performance"
        }

    # 2. Avoid using sensitive emotional inferences to target a person.
    # Emotional state may affect tone and scaffolding only.
    support_level = choose_support_level(user_emotional_state)

    # 3. Filter candidates for educational relevance and privacy.
    candidates = [
        peer for peer in peer_database
        if peer["user_id"] != current_user_id
        and peer["consent_for_anonymized_benchmarking"]
        and matches_learning_context(peer, learning_context)
        and peer["sample_size"] >= MINIMUM_AGGREGATION_THRESHOLD
    ]

    if not candidates:
        return {
            "mode": "personal_progress_feedback",
            "action": "show_mastery_trend"
        }

    # 4. Select the comparison strategy transparently.
    strategy = user_preferences.get("comparison_strategy", "ask_each_time")

    if strategy == "ask_each_time":
        return {
            "mode": "choice",
            "prompt": "Would you like an encouraging example, an advanced benchmark, or your own progress trend?",
            "options": [
                "relatability_example",
                "aspiration_benchmark",
                "personal_progress"
            ]
        }

    if strategy == "relatability":
        return build_relatability_example(
            candidates,
            learning_context,
            support_level
        )

    if strategy == "aspiration":
        return build_aspiration_benchmark(
            candidates,
            learning_context,
            support_level
        )

    return {
        "mode": "personal_progress_feedback",
        "action": "show_mastery_trend"
    }


def build_relatability_example(candidates, learning_context, support_level):
    """
    Show an anonymized, representative learning path—not a real person's identity.
    Prefer examples that normalize common mistakes and show recoverable progress.
    """

    suitable = [
        p for p in candidates
        if p["mastery_band"] in {"similar", "slightly_above"}
        and p["has_documented_revision_path"]
    ]

    example = select_representative_aggregate(suitable)

    return {
        "mode": "relatability",
        "content": {
            "title": "A common learning path",
            "message": (
                "Learners at a similar stage often struggled with this concept "
                "before improving through targeted practice."
            ),
            "next_step": recommend_next_step(example, learning_context)
        },
        "privacy": "aggregated_anonymous",
        "pressure_free": True
    }


def build_aspiration_benchmark(candidates, learning_context, support_level):
    """
    Provide an attainable next milestone, not an extreme outlier or ranking.
    """

    suitable = [
        p for p in candidates
        if p["mastery_band"] in {"moderately_above", "advanced"}
        and p["path_is_reproducible"]
    ]

    benchmark = select_attainable_benchmark(
        suitable,
        current_context=learning_context,
        exclude_outliers=True
    )

    return {
        "mode": "aspiration",
        "content": {
            "title": "A possible next milestone",
            "benchmark": benchmark["skill_milestone"],
            "estimated_practice": benchmark["typical_practice_range"],
            "message": (
                "This is an optional next target. You can choose a smaller step "
                "or continue with your current plan."
            ),
            "next_step": benchmark["recommended_next_step"]
        },
        "privacy": "aggregated_anonymous",
        "pressure_free": True
    }
