def select_peer_for_motivation(
    current_user_id,
    user_emotional_state,
    peer_database,
    user_profile,
    comparison_preferences
):
    """
    Returns an anonymized peer archetype or cohort benchmark.

    Strategies:
      - aspiration_target: demonstrates a realistic next level
      - relatability_target: demonstrates a similar learner path

    Emotional state is treated as uncertain context, not as a diagnosis.
    """

    # 1. Respect consent and student control
    if not comparison_preferences.get("peer_comparison_opt_in", False):
        return {
            "action": "no_comparison",
            "reason": "Peer comparison is disabled"
        }

    if comparison_preferences.get("pause_comparisons", False):
        return {
            "action": "no_comparison",
            "reason": "Student has paused comparisons"
        }

    # 2. Use only appropriate, privacy-preserving records
    eligible_peers = [
        peer for peer in peer_database
        if (
            peer.get("is_anonymized", False)
            and peer.get("consented_for_aggregate_use", False)
            and peer.get("minimum_cohort_size_met", False)
            and peer.get("subject") == user_profile.get("subject")
            and peer.get("level") == user_profile.get("level")
        )
    ]

    if not eligible_peers:
        return {
            "action": "use_personal_progress",
            "message": "Compare against your previous performance instead."
        }

    # 3. Avoid sensitive or manipulative targeting
    # Emotional state may alter presentation or suggest a pause,
    # but should not be used to exploit distress.
    if user_emotional_state.get("confidence", 0) < 0.60:
        emotional_context = "uncertain"
    else:
        emotional_context = classify_broad_learning_context(
            user_emotional_state
        )
        # Allowed outputs: "ready_for_challenge", "needs_reassurance",
        # "neutral", "uncertain"
        # Never infer diagnoses or protected traits.

    if emotional_context == "needs_reassurance":
        strategy = "relatability_target"
    elif emotional_context == "ready_for_challenge":
        strategy = "aspiration_target"
    else:
        strategy = comparison_preferences.get(
            "default_strategy",
            "relatability_target"
        )

    # 4. Define a constructive comparison window
    user_mastery = user_profile.get("mastery_score", 0.0)
    user_recent_growth = user_profile.get("recent_growth", 0.0)

    if strategy == "aspiration_target":
        # Select a realistic next step, not the top performer.
        candidates = [
            peer for peer in eligible_peers
            if (
                peer["mastery_score"] > user_mastery
                and peer["mastery_score"] - user_mastery <= 0.15
                and peer.get("growth_story_available", False)
            )
        ]

        if not candidates:
            strategy = "relatability_target"

    if strategy == "relatability_target":
        candidates = [
            peer for peer in eligible_peers
            if (
                abs(peer["starting_level"] -
                    user_profile.get("starting_level", user_mastery)) <= 0.15
                and peer.get("growth_story_available", False)
            )
        ]

    if not candidates:
        return {
            "action": "use_personal_progress",
            "message": "Your recent progress is the most relevant benchmark."
        }

    # 5. Rank for relevance, not status or popularity
    selected = max(
        candidates,
        key=lambda peer: (
            similarity(peer, user_profile)
            + 0.5 * peer.get("growth_consistency", 0.0)
            + 0.3 * peer.get("strategy_relevance", 0.0)
            - 0.5 * peer.get("comparison_risk", 0.0)
        )
    )

    # 6. Return an aggregate/archetype presentation
    if strategy == "aspiration_target":
        message = (
            "Learners at the next stage often improved by using this approach: "
            f"{selected['effective_strategy']}. "
            "Would you like to try it?"
        )
    else:
        message = (
            "Learners who started at a similar level often made progress by "
            f"using this approach: {selected['effective_strategy']}. "
            "Would you like to see an example?"
        )

    return {
        "action": "show_peer_archetype",
        "strategy": strategy,
        "archetype_id": selected["anonymized_archetype_id"],
        "message": message,
        "options": [
            "show_example",
            "try_strategy",
            "compare_personal_progress",
            "dismiss"
        ],
        "disclosure": (
            "This is an anonymized aggregate pattern, not an identifiable student."
        ),
        "dismissible": True
    }
